def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (after '+')
        if '+' in v:
            v = v.split('+')[0]

        # Split into base version and pre-release
        if '-' in v:
            base, prerelease = v.split('-', 1)
        else:
            base = v
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            for identifier in prerelease.split('.'):
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))

        return (major, minor, patch, prerelease_identifiers)

    def compare_key(v):
        major, minor, patch, prerelease = parse_version(v)
        # Return tuple for sorting:
        # - (major, minor, patch) for numeric comparison
        # - Length of prerelease (0 if no prerelease, so it sorts after with prerelease)
        # - Prerelease identifiers for comparison
        has_prerelease = len(prerelease) > 0
        return (major, minor, patch, has_prerelease, prerelease)

    # Sort using the comparison key, maintaining input order for equal versions
    return sorted(versions, key=compare_key)

